    queued_decisions = activity_next_unlocks or (
        snapshot.get("next_actions") if isinstance(snapshot.get("next_actions"), list) else []
    )
    projections = snapshot.get("projections") if isinstance(snapshot.get("projections"), dict) else {}
    projection_items = [
        ("automation_activity", projections.get("automation_activity") if isinstance(projections.get("automation_activity"), dict) else snapshot.get("projection")),
        ("execution_dag", projections.get("execution_dag") if isinstance(projections.get("execution_dag"), dict) else {}),
        ("runner", projections.get("runner") if isinstance(projections.get("runner"), dict) else {}),
    ]

    status = str(automation_control.get("status") or last_event.get("status") or "ACTIVE")
    if status not in STATUS_MODEL:
        status = "ACTIVE" if str(snapshot.get("status") or "") == "ok" else "ACTIVE_WITH_PENDING_USER_INPUT"

    lines = [
        "# Canonical State Brief",
        "",
        f"- generated_at: {generated_at}",
        "- authority: SQLite orchestration state is canonical; this file is a generated view for agents.",
        f"- database: `{_display_path(target, database.get('path'))}`",
        f"- database_exists: {_brief_bool(database.get('exists'))}",
        f"- sqlite_integrity: {_brief_text(database.get('integrity_check') or 'unknown')}",
        f"- runtime_status: `{status}`",
        f"- current_horizon: {_brief_text(automation_control.get('horizon') or 'unknown')}",
        f"- horizon_decision: {_brief_text(automation_control.get('horizon_decision') or 'unknown')}",
        f"- best_next_milestone: {_brief_text(automation_control.get('best_next_milestone') or 'No milestone recorded yet.')}",
        f"- suggested_next_task: {_brief_text(automation_control.get('suggested_next_task') or 'No sprint task recorded yet.')}",
        "- agent_rule: read this brief at run start; do not inspect or edit the SQLite database manually.",
        "- reconciliation_rule: if Markdown or JSON projections disagree with this brief, regenerate/reconcile through Diffmogger typed state APIs.",
        "",
        "## Last State Change",
        "",
        f"- event: {_format_key_values({'id': last_event.get('event_id'), 'type': last_event.get('event_type'), 'role': last_event.get('actor_role'), 'phase': last_event.get('phase'), 'status': last_event.get('status'), 'at': last_event.get('occurred_at'), 'hash': _brief_sha(last_event.get('event_hash'))})}",
        f"- checkpoint: {_format_key_values({'id': last_checkpoint.get('checkpoint_id'), 'kind': last_checkpoint.get('kind'), 'sequence': last_checkpoint.get('sequence'), 'at': last_checkpoint.get('created_at'), 'sha': _brief_sha(last_checkpoint.get('state_sha256'))})}",
        "",
        "## Performance Guardrails",
        "",
        f"- timing_summary: {_format_key_values({'slow_threshold_ms': runtime_performance.get('slow_phase_threshold_ms'), 'latest_samples': len(latest_phase_timings), 'slow_warnings': len(slow_phase_warnings)})}",
        f"- graph_storage: {_format_key_values({'truncated': _brief_bool(graph_summary.get('storage_truncated')), 'file_limit': (graph_summary.get('snapshot_storage') or {}).get('limits', {}).get('file') if isinstance(graph_summary.get('snapshot_storage'), dict) and isinstance((graph_summary.get('snapshot_storage') or {}).get('limits'), dict) else '', 'symbol_limit': (graph_summary.get('snapshot_storage') or {}).get('limits', {}).get('symbol') if isinstance(graph_summary.get('snapshot_storage'), dict) and isinstance((graph_summary.get('snapshot_storage') or {}).get('limits'), dict) else '', 'edge_limit': (graph_summary.get('snapshot_storage') or {}).get('limits', {}).get('edge') if isinstance(graph_summary.get('snapshot_storage'), dict) and isinstance((graph_summary.get('snapshot_storage') or {}).get('limits'), dict) else ''})}",
    ]
    for item in latest_phase_timings[:4]:
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- phase_timing: {_format_key_values({'phase': item.get('phase'), 'ms': item.get('elapsed_ms'), 'status': item.get('status'), 'source': item.get('source')})}"
        )
    for item in slow_phase_warnings[:4]:
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- slow_phase: {_format_key_values({'phase': item.get('phase'), 'ms': item.get('elapsed_ms'), 'source': item.get('source'), 'status': item.get('status')})}"
        )
    lines.extend([
        "",
        "## Execution DAG",
        "",
        f"- summary: {_format_key_values({'digest': _brief_sha(execution_dag.get('digest')), 'nodes': execution_dag.get('node_count'), 'edges': execution_dag.get('edge_count'), 'ready': len(dag_ready), 'active': len(dag_active), 'blocked': len(dag_blocked)})}",
        f"- primary_node: {_format_key_values({'task': dag_primary.get('task_id') or dag_primary.get('id'), 'action': dag_primary.get('action_type'), 'status': dag_primary.get('status'), 'owner': dag_primary.get('owner_role'), 'confidence': dag_primary.get('confidence')})}",
    ])
    if dag_active:
        for item in dag_active[:BRIEF_ITEM_LIMIT]:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- active_node: {_format_key_values({'task': item.get('task_id') or item.get('id'), 'action': item.get('action_type'), 'owner': item.get('owner_role'), 'attempts': item.get('attempt_count'), 'summary': item.get('summary')})}"
            )
    if dag_ready:
        for item in dag_ready[:BRIEF_ITEM_LIMIT]:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- ready_node: {_format_key_values({'task': item.get('task_id') or item.get('id'), 'action': item.get('action_type'), 'owner': item.get('owner_role'), 'receipts': len(item.get('validation_receipt_refs') if isinstance(item.get('validation_receipt_refs'), list) else []), 'summary': item.get('summary')})}"
            )
    else:
        lines.append("- ready_node: none")
    if dag_blocked:
        for item in dag_blocked[:BRIEF_ITEM_LIMIT]:
            if not isinstance(item, dict):
                continue
            reasons = item.get("blocked_reasons") if isinstance(item.get("blocked_reasons"), list) else []
            first_reason = reasons[0] if reasons and isinstance(reasons[0], dict) else {}
            lines.append(
                f"- blocked_node: {_format_key_values({'task': item.get('task_id') or item.get('id'), 'action': item.get('action_type'), 'status': item.get('status'), 'reason': first_reason.get('reason') or item.get('blocker_reason')})}"
            )
    else:
        lines.append("- blocked_node: none")
    lines.extend([
        "",
        "## Runtime Activity",
        "",
        f"- activity: {_format_key_values({'digest': _brief_sha(automation_activity.get('digest')), 'nodes': activity_summary.get('node_count'), 'edges': activity_summary.get('edge_count'), 'lanes': activity_summary.get('lane_count'), 'waves': activity_summary.get('wave_count'), 'health': activity_health.get('status')})}",
        f"- repo_capabilities: {_format_key_values({'primary_language': capability_languages.get('primary'), 'manifest_version': capability_manifest.get('version'), 'digest': _brief_sha(capability_manifest.get('digest')), 'commands': len(capability_manifest.get('commands') if isinstance(capability_manifest.get('commands'), list) else [])})}",
        f"- codebase_graph: {_format_key_values({'namespace': graph_summary.get('graph_namespace'), 'digest': _brief_sha(latest_graph.get('digest')), 'files': graph_summary.get('indexed_file_count'), 'symbols': (graph_summary.get('node_counts') or {}).get('symbol') if isinstance(graph_summary.get('node_counts'), dict) else 0, 'imports': (graph_summary.get('edge_counts') or {}).get('imports') if isinstance(graph_summary.get('edge_counts'), dict) else 0, 'ownership': (graph_summary.get('edge_counts') or {}).get('owns_symbol') if isinstance(graph_summary.get('edge_counts'), dict) else 0, 'commands': graph_summary.get('command_node_count'), 'tests': graph_summary.get('test_node_count'), 'stale': graph_summary.get('stale_node_count'), 'truncated': _brief_bool(graph_summary.get('storage_truncated'))})}",
        f"- impact_graph: {_format_key_values({'namespace': impact_summary.get('graph_namespace'), 'digest': _brief_sha(impact_latest.get('digest')), 'edges': impact_latest.get('edge_count'), 'stale': impact_summary.get('stale_node_count')})}",
        f"- selected_activity: {_format_key_values({'role': selected_activity_candidate.get('role'), 'task': selected_activity_candidate.get('task_id') or selected_activity_candidate.get('public_task_id'), 'action': selected_activity_candidate.get('action_kind'), 'score': selected_activity_candidate.get('score')})}",
        f"- active_run: {_format_key_values({'role': active_role.get('role'), 'run_id': active_role.get('run_id'), 'status': active_role.get('status'), 'started_at': active_role.get('started_at'), 'reason': active_role.get('reason')})}",
        f"- runner: {_format_key_values({'state': runner_state.get('state'), 'pid': runner_state.get('pid'), 'run_id': runner_state.get('run_id'), 'started_at': runner_state.get('started_at'), 'updated_at': runner_state.get('updated_at')})}",
        f"- human_messages: {_format_key_values({'pending_requests': human_counts.get('pending_requests'), 'queued_notes': human_counts.get('queued_notes'), 'failed_notes': human_counts.get('failed_notes'), 'outbound_records': human_counts.get('outbound_records')})}",
        f"- ticket_run: {_format_key_values({'status': ticket_state.get('status'), 'run_id': ticket_state.get('run_id'), 'total': ticket_state.get('total'), 'counts': stable_json(ticket_state.get('counts')) if isinstance(ticket_state.get('counts'), dict) else ''})}",
        "",
        "## Graph Context For Next Action",
        "",
    ])
    selected_task = context_pack.get("selected_task") if isinstance(context_pack.get("selected_task"), dict) else {}
    lines.append(
        f"- selected_task: {_format_key_values({'kind': selected_task.get('kind'), 'id': selected_task.get('id'), 'status': selected_task.get('status'), 'summary': selected_task.get('summary')})}"
    )
    if stale_context_warning:
        lines.append(f"- stale_warning: {_brief_text(stale_context_warning)}")
    policy_notes = context_pack.get("policy_notes") if isinstance(context_pack.get("policy_notes"), list) else []
    if policy_notes:
        lines.append(f"- policy: {_brief_text('; '.join(str(item) for item in policy_notes), limit=220)}")
    context_items = context_pack.get("items") if isinstance(context_pack.get("items"), list) else []
    if context_items:
        for item in context_items[:BRIEF_ITEM_LIMIT]:
            if not isinstance(item, dict):
                continue
            label = item.get("path") or item.get("name") or item.get("node_id")
            lines.append(
                f"- {str(item.get('category') or item.get('kind') or 'context')}: `{_brief_text(label, limit=140)}` confidence={float(item.get('confidence') or 0):.2f} reason={_brief_text(item.get('reason'), limit=160)} stale={_brief_bool(item.get('is_stale'))}"
            )
    else:
        lines.append("- none")
    lines.extend([
        "",
        "## Scheduler Decision",
        "",
    ])
    if selected_scheduler:
        selected_context = (
            selected_scheduler.get("context_pack_preview")
            if isinstance(selected_scheduler.get("context_pack_preview"), dict)
            else {}
        )
        selected_context_items = (
            selected_context.get("items") if isinstance(selected_context.get("items"), list) else []
        )
        selected_leases = (
            selected_scheduler.get("required_leases")
            if isinstance(selected_scheduler.get("required_leases"), list)
            else []
        )
        selected_reasons = selected_scheduler.get("reasons") if isinstance(selected_scheduler.get("reasons"), list) else []
        lines.append(
            f"- selected_candidate: {_format_key_values({'id': selected_scheduler.get('candidate_id'), 'role': selected_scheduler.get('role'), 'task': selected_scheduler.get('public_task_id') or selected_scheduler.get('task_id'), 'action': selected_scheduler.get('action_kind'), 'score': selected_scheduler.get('score')})}"
        )
        if selected_reasons:
            lines.append(f"- selected_reasons: {_brief_text('; '.join(str(item) for item in selected_reasons[:3]), limit=260)}")
        if selected_context.get("stale_context_warning"):
            lines.append(f"- stale_context_warning: {_brief_text(selected_context.get('stale_context_warning'))}")
        if selected_context_items:
            for item in selected_context_items[:4]:
                if not isinstance(item, dict):
                    continue
                label = item.get("path") or item.get("name") or item.get("category")
                lines.append(
                    f"- context: `{_brief_text(label, limit=120)}` confidence={float(item.get('confidence') or 0):.2f} reason={_brief_text(item.get('reason'), limit=140)}"
                )
        if selected_leases:
            for lease in selected_leases[:4]:
                if not isinstance(lease, dict):
                    continue
                label = lease.get("path") or lease.get("name") or lease.get("scope_node_id")
                lines.append(
                    f"- suggested_lease: {_format_key_values({'scope': lease.get('scope_kind'), 'target': label, 'recommended': _brief_bool(lease.get('recommended')), 'conflicts': lease.get('conflict_count'), 'reason': lease.get('reason')})}"
                )
        else:
            lines.append("- suggested_lease: none")
    else:
        lines.append("- selected_candidate: none")
    if skipped_scheduler:
        for candidate in skipped_scheduler[:BRIEF_ITEM_LIMIT]:
            if not isinstance(candidate, dict):
                continue
            lines.append(
                f"- skipped_candidate: {_format_key_values({'id': candidate.get('candidate_id'), 'role': candidate.get('role'), 'task': candidate.get('public_task_id') or candidate.get('task_id'), 'action': candidate.get('action_kind'), 'reason': candidate.get('skipped_reason')})}"
            )
    else:
        lines.append("- skipped_candidate: none")
    lines.extend([
        "",
        "## Parallel Execution",
        "",
        f"- summary: {_format_key_values({'display_mode': parallelization_summary.get('display_mode_label') or parallelization_summary.get('display_mode') or 'Planning preview', 'proposed': parallelization_summary.get('group_count'), 'running': len(active_execution_groups), 'recently_completed': len(recent_execution_groups), 'grouped_tasks': parallelization_summary.get('grouped_task_count'), 'reasons': parallelization_summary.get('blocked_candidate_count'), 'top_reason': parallelization_summary.get('top_blocked_reason_kind')})}",
        f"- active_counts: {_format_key_values(active_parallel_counts)}",
        f"- worker_reports: {_format_key_values({'active_read_only': len(active_read_only_workers), 'active_write': len(active_write_workers), 'completed': len(completed_worker_reports), 'disposition_required': _brief_bool(worker_finding_disposition_required), 'awaiting_integrator_review': worker_disposition_summary.get('awaiting_integrator_review_count'), 'pending_disposition': worker_disposition_summary.get('pending_count')})}",
        f"- worker_dispositions: {_format_key_values(worker_disposition_counts)}",
        f"- scope_fanout: {_format_key_values({'outcomes': len(scope_fanout_outcomes), 'exhausted': len(exhausted_scope_fanout_outcomes), 'max_completed_attempts': SCOPE_FANOUT_MAX_COMPLETED_ATTEMPTS})}",
        f"- worker_patches: {_format_key_values({'queued': len(queued_worker_patches), 'conflicts': len(write_worker_conflicts)})}",
        f"- worker_patch_preflight: {_format_key_values({'safe': worker_patch_preflight.get('safe_count'), 'ready': worker_patch_preflight.get('ready_patch_count'), 'already_applied': worker_patch_preflight.get('already_applied_count'), 'rebaseable': worker_patch_preflight.get('rebaseable_count'), 'reconcilable': worker_patch_preflight.get('reconcilable_overlap_count'), 'true_conflict': worker_patch_preflight.get('true_conflict_count'), 'missing_metadata': worker_patch_preflight.get('missing_metadata_count')})}",
        f"- patch_lineage: {_format_key_values({'count': (snapshot.get('patch_lineage_summary') or {}).get('lineage_count') if isinstance(snapshot.get('patch_lineage_summary'), dict) else 0, 'file_f1': patch_prediction_accuracy.get('average_file_f1'), 'symbol_f1': patch_prediction_accuracy.get('average_symbol_f1'), 'conflict_rate': patch_telemetry.get('conflict_rate'), 'validation_failure_rate': patch_telemetry.get('validation_failure_rate'), 'retry_rate': patch_telemetry.get('retry_rate'), 'integration_success_rate': patch_telemetry.get('integration_success_rate'), 'wall_clock_saved_s': patch_telemetry.get('wall_clock_savings_seconds')})}",
        f"- validation_jobs: {_format_key_values({'aggregate': validation_job_summary.get('aggregate_status'), 'active': len(active_validation_jobs), 'total': validation_job_summary.get('job_count'), 'available': _brief_bool(snapshot.get('parallel_validation_available')), 'budget_allowed': _brief_bool(validation_budget_status.get('allowed'))})}",
    ])
    for item in worker_patch_preflight_order[:BRIEF_ITEM_LIMIT]:
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- integration_preflight_order: {_format_key_values({'order': item.get('safe_order'), 'patch': item.get('patch_id'), 'status': item.get('status'), 'ready': _brief_bool(item.get('ready_to_integrate')), 'reason': item.get('reason_kind')})}"
        )
    for item in worker_patch_preflight_conflicts[:BRIEF_ITEM_LIMIT]:
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- integration_preflight_conflict: {_format_key_values({'patch': item.get('patch_id'), 'conflicts': ','.join(str(value) for value in item.get('conflict_patch_ids') or []), 'kind': item.get('reason_kind')})}"
        )
    if parallelism_budgets:
        for budget in parallelism_budgets[:BRIEF_ITEM_LIMIT]:
            if not isinstance(budget, dict):
                continue
            lines.append(
                f"- budget: {_format_key_values({'scope': budget.get('scope'), 'enabled': _brief_bool(budget.get('enabled')), 'max': budget.get('max_concurrent'), 'runtime_s': budget.get('max_runtime_seconds'), 'source': budget.get('source')})}"
            )
    else:
        lines.append("- budget: none")
    if budget_exhaustion_reasons:
        for reason in budget_exhaustion_reasons[:BRIEF_ITEM_LIMIT]:
            if not isinstance(reason, dict):
                continue
            lines.append(
                f"- budget_limit: {_format_key_values({'scope': reason.get('scope'), 'kind': reason.get('reason_kind'), 'active': reason.get('active'), 'max': reason.get('max_concurrent'), 'reason': reason.get('reason')})}"
            )
    for outcome in exhausted_scope_fanout_outcomes[:BRIEF_ITEM_LIMIT]:
        if not isinstance(outcome, dict):
            continue
        top_reasons = outcome.get("top_rejection_reasons") if isinstance(outcome.get("top_rejection_reasons"), list) else []
        top_reason = top_reasons[0].get("reason_kind") if top_reasons and isinstance(top_reasons[0], dict) else ""
        lines.append(
            f"- serial_fallback: {_format_key_values({'task': outcome.get('task_id'), 'attempts': outcome.get('attempt_count'), 'records': outcome.get('evidence_record_count'), 'accepted': outcome.get('accepted_count'), 'top_rejection': top_reason, 'reason': 'No promotable ownership evidence; using serial fallback.', 'raw_reason': 'scope_fanout_exhausted'})}"
        )
    if completed_worker_reports:
        for worker in completed_worker_reports[:BRIEF_ITEM_LIMIT]:
            if not isinstance(worker, dict):
                continue
            lines.append(
                f"- worker_report: {_format_key_values({'worker': worker.get('worker_id'), 'mode': worker.get('mode'), 'status': worker.get('status'), 'disposition': worker.get('disposition_label') or worker.get('disposition_status'), 'detail': worker.get('disposition_summary')})}"
            )
    if proposed_execution_groups:
        lines.append("- proposed_groups: Planning preview")
        for group in proposed_execution_groups[:BRIEF_ITEM_LIMIT]:
            if not isinstance(group, dict):
                continue
            items = group.get("items") if isinstance(group.get("items"), list) else []
            payload = group.get("payload") if isinstance(group.get("payload"), dict) else {}
            lines.append(
                f"- proposed_group: {_format_key_values({'id': group.get('execution_group_id'), 'display': group.get('display_mode_label') or payload.get('display_mode_label') or 'Planning preview', 'execution': group.get('execution_mode_label') or payload.get('execution_mode_label') or payload.get('execution_mode'), 'items': len(items), 'reason': group.get('reason')})}"
            )
            if payload.get("why_together"):
                lines.append(f"- why_together: {_brief_text(payload.get('why_together'), limit=240)}")
            for item in items[:4]:
                if not isinstance(item, dict):
                    continue
                item_payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
                context_preview = item_payload.get("context_pack_preview") if isinstance(item_payload.get("context_pack_preview"), dict) else {}
                context_items = context_preview.get("items") if isinstance(context_preview.get("items"), list) else []
